import json
import requests
import chardet
# Constants
API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    if not isinstance(url, str) or not url:
        raise ValueError("Invalid URL provided.")

    try:
        response = requests.get(url, timeout=5)
        response.raise_for_status()
        content = response.content
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to retrieve data from {url}: {e}")

    if not content:
        return {}

    encoding_result = chardet.detect(content)
    detected_encoding = encoding_result['encoding']

    if not detected_encoding:
        raise ValueError("Unable to detect encoding for non-empty content")

    try:
        decoded_content = content.decode(detected_encoding if from_encoding is None else from_encoding)
        re_encoded_content = decoded_content.encode(to_encoding)
        json_data = json.loads(re_encoded_content)
    except Exception as e:
        raise ValueError(f"Error processing the content: {e}")

    return json_data

import ast
import requests
from bs4 import BeautifulSoup

def task_func(url):
    if not url:
        raise ValueError("URL must be a non-empty string.")

    try:
        response = requests.get(url)
        response.raise_for_status()
        soup = BeautifulSoup(response.text, 'html.parser')
        scripts = soup.find_all('script')

        evaluated_dicts = []
        for script in scripts:
            script_content = script.string
            if script_content:
                try:
                    evaluated = ast.literal_eval(script_content)
                    if isinstance(evaluated, dict):
                        evaluated_dicts.append(evaluated)
                except (ValueError, SyntaxError):
                    pass

        return evaluated_dicts
    except requests.RequestException:
        return []

